(async()=>{const out={},c=new OfflineAudioContext(1,1024,48000),n=c.createDynamicsCompressor(),err=f=>{try{f();return null}catch(e){return e.name}};
out.defaults=[n.numberOfInputs,n.numberOfOutputs,n.channelCount,n.channelCountMode,n.channelInterpretation,n.reduction,...['threshold','knee','ratio','attack','release'].map(k=>{const p=n[k];return[p.value,p.defaultValue,p.minValue,p.maxValue,p.automationRate,err(()=>p.automationRate='a-rate')]})];
out.channels=[1,2,3].map(v=>[v,err(()=>n.channelCount=v),n.channelCount]);out.modes=['max','clamped-max','explicit','bad'].map(v=>[v,err(()=>n.channelCountMode=v),n.channelCountMode]);
out.wave=[err(()=>new PeriodicWave(c)),err(()=>new OscillatorNode(c,{type:'bad'})),err(()=>new OscillatorNode(c,{type:'custom'})),err(()=>new OscillatorNode(c,{periodicWave:new PeriodicWave(new OfflineAudioContext(1,8,8000))}))];
for(const config of [{},{threshold:-50,knee:40,ratio:12,attack:0,release:.25},{ratio:1},{threshold:-10,knee:0,ratio:4,attack:.01,release:.1}]){const c=new OfflineAudioContext(1,4096,48000),s=c.createBufferSource(),n=new DynamicsCompressorNode(c,config);s.buffer=c.createBuffer(1,4096,48000);const d=s.buffer.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=i<2048?Math.sin(2*Math.PI*i/48):0;s.connect(n);n.connect(c.destination);s.start();const b=await c.startRendering();out['pcm'+JSON.stringify(config)]={data:Array.from(b.getChannelData(0)),reduction:n.reduction};}
return out;})()
